import{_ as a,o as i,c as s,a8 as t}from"./chunks/framework.R_sesYpn.js";const u=JSON.parse('{"title":"Miscellaneous","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index-your-data/miscellaneous.md","filePath":"guide/030_index-your-data/090_miscellaneous.md","lastUpdated":1776159914000}'),o={name:"guide/index-your-data/miscellaneous.md"};function n(l,e,d,r,c,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="miscellaneous" tabindex="-1">Miscellaneous <a class="header-anchor" href="#miscellaneous" aria-label="Permalink to &quot;Miscellaneous&quot;">​</a></h1> <h2 id="forward-index-and-multiple-values" tabindex="-1">Forward index and multiple values <a class="header-anchor" href="#forward-index-and-multiple-values" aria-label="Permalink to &quot;Forward index and multiple values&quot;">​</a></h2> <p>A note about forward indexes and indexing multiple values at a single corpus position: as of right now, the forward index will only store the first value indexed at any position. This is the value used for grouping and sorting on this annotation. In the future we may add the ability to store multiple values for a token position in the forward index, although it is likely that the first value will always be the one used for sorting and grouping.</p> <h2 id="allow-viewing-documents" tabindex="-1">Allow viewing documents <a class="header-anchor" href="#allow-viewing-documents" aria-label="Permalink to &quot;Allow viewing documents&quot;">​</a></h2> <p>By default, BlackLab Server will not allow whole documents to be retrieved using <code>/docs/PID/contents</code>. This is to prevent accidentally distributing unlicensed copyrighted material.</p> <p>You can allow retrieving whole documents by enabling the <code>corpusConfig.contentViewable</code> setting in the index format configuration file, or directly in the <code>indexmetadata.yaml</code> file in the index directory.</p> <p>This setting can also be changed for individual documents by setting a metadat field with the name <code>contentViewable</code> to <code>true</code> or <code>false</code>.</p> <h2 id="xpath-support-level" tabindex="-1">XPath support level <a class="header-anchor" href="#xpath-support-level" aria-label="Permalink to &quot;XPath support level&quot;">​</a></h2> <p>BlackLab uses the Saxon library to process XML.</p> <div class="warning custom-block"><p class="custom-block-title">Saxon on BlackLab 4.x</p> <p>BlackLab <code>v4.x</code> used either VTD or Saxon as an XML processor. It is recommended to use Saxon there as well. Place <code>processor: saxon</code> in your <code>.blf.yaml</code> file to ensure you&#39;re using Saxon in that version.</p></div> <p>Saxon supports XPath 3.1, which is very powerful and can help when writing complex indexing configurations.</p> <p>Certain complex indexing features can be avoided when using Saxon; many things can be done in XPath directly. See <a href="./xpath-examples.html">XPath examples</a> to get an idea of the wide range of possibilities.</p> <p>(BlackLab up to version 4 defaulted to the VTD-XML processor and had Saxon as an option (<code>processor: saxon</code> in <code>.blf.yaml</code>). On the development branch (future BlackLab 5), Saxon is now the only supported XML processor)</p> <h2 id="namespaces" tabindex="-1">Namespaces <a class="header-anchor" href="#namespaces" aria-label="Permalink to &quot;Namespaces&quot;">​</a></h2> <p>If your XML documents use namespaces, you must declare these in the <code>namespaces</code> section of your format config file
so your XPath expressions work correctly. Note that the <code>xml</code> namespace is implicit and does not need to be declared (since <code>dev</code>/<code>5.x</code>).</p> <p>Example:</p> <div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">namespaces</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    tei</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://www.tei-c.org/ns/1.0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">## What element starts a new document?</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">documentPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">//tei:TEI</span></span></code></pre></div><p>You can also declare a default namespace (i.e. for elements without a prefix) by using an empty string as the prefix. So the following is equivalent to the above:</p> <div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">namespaces</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://www.tei-c.org/ns/1.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">documentPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">//TEI</span></span></code></pre></div><p>Note that if you do not declare namespaces in your <code>.blf.yaml</code> file, namespaces will be ignored during indexing. This can help to index &#39;messy&#39; datasets where some documents have schema declarations and other do not.</p> <h2 id="unicode-normalization" tabindex="-1">Unicode normalization <a class="header-anchor" href="#unicode-normalization" aria-label="Permalink to &quot;Unicode normalization&quot;">​</a></h2> <p>Unicode normalization refers to the process of converting different ways of encoding the same character to a single, canonical form. For example, the character <code>é</code> can be encoded as a single character <code>é</code> (U+00E9), or as a combination of <code>e</code> (U+0065) and <code>´</code> (U+00B4).</p> <p>BlackLab&#39;s builtin indexers should automatically normalize to NFC (Normalization Form Canonical Composition). This should prevent any issues when sorting or grouping.</p> <p><a href="https://en.wikipedia.org/wiki/Unicode_equivalence" target="_blank" rel="noreferrer">More about Unicode equivalence and normal forms</a></p> <h2 id="automatic-xslt-generation" tabindex="-1">Automatic XSLT generation <a class="header-anchor" href="#automatic-xslt-generation" aria-label="Permalink to &quot;Automatic XSLT generation&quot;">​</a></h2> <p>If you&#39;re creating your own corpora by uploading data to BlackLab Frontend, you want to be able to view your documents as well, without having to write an XSLT yourself. BlackLab Server can generate a default XSLT from your format config file. However, because BlackLab is a bit more lenient with namespaces than the XSLT processor that generates the document view, the generated XSLT will only work correctly if you take care to define your namespaces correctly in your format config file.</p> <p>IMPORTANT: generating the XSLT might not work correctly if your XML namespaces change throughout the document, e.g. if you declare local namespaces on elements, instead of</p> <p>Namespaces can be declared in the top-level &quot;namespaces&quot; block, which is simply a map of namespace prefix (e.g. &quot;tei&quot;) to the namespace URI (e.g. <code>http://www.tei-c.org/ns/1.0</code>). So for example, if your documents declare namespaces as follows:</p> <div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">doc</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xmlns:my-ns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://example.com/my-ns&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xmlns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://example.com/other-ns&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">doc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Then your format config file should contain this namespaces section:</p> <div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">namespaces</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://example.com/other-ns</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # The default namespace</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  my-ns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://example.com/my-ns</span></span></code></pre></div><p>If you forget to declare some or all of these namespaces, the document might index correctly, but the generated XSLT won&#39;t work and will likely show a message saying that no words have been found in the document. Updating your format config file should fix this; re-indexing shouldn&#39;t be necessary, as the XSLT is generated directly from the config file, not the index.</p> <h2 id="configuration-versions-1-and-2" tabindex="-1">Configuration versions 1 and 2 <a class="header-anchor" href="#configuration-versions-1-and-2" aria-label="Permalink to &quot;Configuration versions 1 and 2&quot;">​</a></h2> <p>BlackLab 4 introduced a version 2 of the <code>.blf.yaml</code> format. On <code>dev</code>/<code>5.x</code>, this version is the default, and the <code>version: 2</code> declaration at the top of the format file is no longer necessary.</p> <p>Version 2 of the format file introduced a few breaking changes to be aware of:</p> <ul><li>default XML processor is now <code>saxon</code> (used to be <code>vtd</code>). Saxon is faster and supports modern XPath features, making it much more flexible.</li> <li><code>baseFormat</code> key (to inherit from a different format config) is no longer allowed. Instead, you should copy the format and customize it to suit your needs.</li> <li><code>word</code> and <code>lemma</code> no longer have a special default <code>sensitivity</code>. All user-defined annotations now default to <code>insensitive</code>. To remain compatible with the old behaviour, explicitly specify <code>sensitivity: sensitive_insensitive</code> for <code>word</code> and <code>lemma</code>.</li> <li>dash <code>-</code> in field or annotation name will no longer automatically be replaced with underscore <code>_</code> (this was never necessary; field and annotation names must be valid XML names, which may contain dashes) If you rely on this quirk, replace dash with underscore manually in your config.</li> <li>processing step <code>default</code> was renamed to <code>ifempty</code>, to better describe how it&#39;s commonly used.</li> <li><code>inlineTags</code> keys <code>includeAttributes</code>, <code>excludeAttributes</code> and <code>extraAttributes</code> have been removed. Instead, use the <code>attributes</code> key to specify which attributes to index. Add <code>valuePath</code> if this is an extra attribute (that doesn&#39;t actually appear on the tag, but should be added based on the XPath expression). Use <code>exclude: true</code> to exclude an attribute. If the first entry contains no name, only <code>exclude: true</code>, this means &quot;exclude any attribute not in this list&quot;.</li> <li><code>append</code> processing step now has a <code>prefix</code> parameter in addition to the <code>separator</code> parameter. <code>separator</code> still defaults to a space, but is now only used to separate multiple metadata field values. <code>prefix</code> defaults to the empty string, and is used to prefix the value to be appended. This means you won&#39;t get an extra space by default when appending a value. Add <code>prefix: &#39; &#39;</code> (or whatever you set as <code>separator</code>) for the old behaviour.</li> <li>The <code>multipleValues</code>, <code>allowDuplicateValues</code> keys on an annotations have been removed. Both work automatically now: if your config produces multiple values for an annotation, they will be indexed, and any duplicates that may arise are automatically removed.</li> <li>The <code>mapValues</code> key on metadata fields has been removed. Use the <code>map</code> processing step instead, which can be used anywhere where processing steps are allowed.</li></ul>`,67)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
